  "{n} people have no record for this day: not clocked in and not on leave.": "{n} 人当天没有记录：未打卡也未休假。",
  "{n} people have no shift assigned.": "有 {n} 人未分配班次。",
  "{n} people have not clocked in yet. Some may start later in the day.": "{n} 人尚未打卡。有些人可能当天稍晚上班。",
  "{n} people have not confirmed \"{title}\" yet.": "还有 {n} 人未确认“{title}”。",
  "{n} people have their own figure for at least one leave type instead of the company default.": "有 {n} 人至少有一类假期使用个人设定，而不是公司默认值。",
  "{n} people in {runNo} have no days worked. Check Attendance before approving.": "{runNo} 中有 {n} 人没有出勤天数。批准前请检查考勤。",
  "{n} people on this shift": "此班次有 {n} 人",
  "{n} people plus you. You will be the group admin: you can rename it, change its photo and add or remove people.": "{n} 人加上你。你将是群组管理员：可以重命名群组、更换照片以及添加或移除成员。",
  "{n} people start leave in the next 7 days, the first is {name} on {date}.": "未来 7 天有 {n} 人开始休假，第一位是 {name}，在 {date}。",
  "{n} people who can change access, pay or settings sign in with a password alone. Ask them to turn on two-step sign-in under My space.": "{n} 位可更改访问、薪资或设置的人仅用密码登录。请他们在“我的空间”中开启两步登录。",
  "{n} people who no longer work here can still sign in.": "{n} 位已离职人员仍可登录。",
  "{n} people's days split across leave types do not add up to the total agreed with them.": "有 {n} 人在各类假期中分配的天数与约定总数不符。",
