  "{tenant} is liable for the {amount} repair “{title}”, but it has not been charged.": "{tenant} 应承担 {amount} 的维修“{title}”，但尚未收费。",
  "{tenant} moves into {unit} on {date}.": "{tenant} 将于 {date} 入住 {unit}。",
  "{tenant}'s booking on {unit} ends {date} with no renewal yet.": "{tenant} 在 {unit} 的预订于 {date} 结束，尚未续租。",
  "{tenant}'s booking on {unit} ends {date}. Renew it or start re-letting.": "{tenant} 在 {unit} 的预订于 {date} 结束。请续租或重新招租。",
  "{tenant}'s deposit of {amount} has not been returned since the booking ended.": "{tenant} 的押金 {amount} 在预订结束后仍未退还。",
  "{tenantName} owes a deposit of {amount}; {amount2} has been received so far.": "{tenantName} 应付押金 {amount}；目前已收 {amount2}。",
  "{title} hasn't been built yet — the API behind it is live and tested (see the backend README), it just doesn't have a frontend screen in this pass.": "{title} 尚未构建 — 其背后的 API 已上线并经过测试（参见后端 README），只是本版本中还没有前端界面。",
  "{unit} at {property} has stood empty for {days} days — {rent} a month not coming in.": "{property} 的 {unit} 已空置 {days} 天——每月少收 {rent}。",
  "{unit} at {property} is empty and nobody has been offered it.": "{property} 的 {unit} 空置，且未向任何人报价。",
  "{unit} has had {n} repairs in six months. Worth finding out why.": "{unit} 半年内维修了 {n} 次，值得查明原因。",
  "{unit} has no asking rent set, so a booking on it would be priced at nothing.": "{unit} 未设置要价租金，预订会按零计价。",
  "{unit} is set to sub-metered utilities but has no meter, so its usage can't be billed.": "{unit} 设为分表计费但没有电表，用量无法开票。",
  "{unit}: {tenant}'s booking ends {date}.": "{unit}：{tenant} 的预订于 {date} 结束。",
  "{unitCode} becomes vacant immediately. Any unpaid invoices stay outstanding — ending a tenancy doesn't cancel what's owed.": "{unitCode} 将立即变为空置。任何未付发票仍然有效 — 结束租约不会取消欠款。",
  "{usableLeaveDays} usable in {year} — {leaveDaysTotal} total days already include that year's {holidaysThisYear} company holiday(s), so {holidaysThisYear} of the {leaveDaysTotal} are the public holidays themselves, not extra leave on top.": "{year} 年可用 {usableLeaveDays} 天 — 总计 {leaveDaysTotal} 天已包含当年 {holidaysThisYear} 天公司假日，因此 {leaveDaysTotal} 天中有 {holidaysThisYear} 天就是公共假日本身，而不是额外的假期。",
  "{use} in use": "{use} 台在用",
  "{use} in use · {spare} spare": "{use} 台在用 · {spare} 台备用",
  "{used} days taken in {year}": "{year} 年已休 {used} 天",
  "{used} of {granted} days taken in {year}": "{year} 年已休 {used} 天（共 {granted} 天）",
  "{used} used": "已用 {used}",
  "{used} used, {off} written off, {left} left": "已用 {used}，报废 {off}，剩余 {left}",
  "{waybillNo} cancelled.": "{waybillNo} 已取消。",
  "{waybillNo} delivered": "{waybillNo} 已送达",
  "{waybillNo} delivered.": "{waybillNo} 已送达。",
  "{waybillNo} dispatched.": "{waybillNo} 已发货。",
  "{waybillNo} is back on the road.": "{waybillNo} 已重新标记为运输中。",
  "{what} · {days} days late": "{what} · 逾期 {days} 天",
  "{what} · due {date}": "{what} · {date} 到期",
  "{what} · due in {days} days": "{what} · {days} 天后到期",
  "{what} · due today": "{what} · 今天到期",
  "{what} for {name} is due to be invoiced today. It goes out with the morning run, or bill it now.": "{name} 的{what}今天应开具发票。它会随早间运行发出，也可以现在开票。",
  "{who} has {n} items checked out.": "{who} 借出了 {n} 件物品。",
  "{with} of {orders} orders in the last {n} days. The higher this is, the better you know your diners.": "最近 {n} 天 {orders} 笔订单中的 {with} 笔。比例越高，您就越了解您的食客。",
  "{won} of {n} ({pct}%)": "{n} 份中 {won} 份（{pct}%）",
  "{won} of {n} quotations answered in the period were won ({pct}%).": "该期间已答复的 {n} 份报价中赢得 {won} 份（{pct}%）。",
  "{won} won, {lost} lost or expired, last 90 days": "过去 90 天：赢 {won} 份，输或过期 {lost} 份",
  "{worked} of {expected} expected days worked": "应到 {expected} 天中工作了 {worked} 天",
  "{worstMinutes} min · {worstDate}": "{worstMinutes} 分钟 · {worstDate}",
  "{year} balance": "{year} 年余额",
  "{year} balance for {type}": "{type}的 {year} 年余额",
