  "1 lead or prospect has never had a quotation.": "有 1 个线索或潜在客户从未收到报价。",
  "1 lead or prospect has no account manager, so nobody owns the follow-up.": "有 1 个线索或潜在客户没有客户经理，因此无人负责跟进。",
  "1 leave request is waiting for a decision.": "有 1 份请假申请等待决定。",
