  "1 person": "1 人",
  "1 person came in late today.": "今天有 1 人迟到。",
  "1 person came in on time every day they were expected.": "有 1 人在每个应到日都准时到岗。",
  "1 person forgot to clock out and was clocked out by the system. Correct it if you know the real time.": "有 1 人忘记下班打卡，由系统自动打卡。如知道实际时间请更正。",
  "1 person has no shift assigned.": "有 1 人未分配班次。",
