  "1 product has no cost price yet": "1 个产品尚无成本价",
  "1 product is at or below its reorder level.": "有 1 种产品达到或低于再订购水平。",
  "1 question": "1 个问题",
  "1 quotation expires within a week: a good moment to call.": "有 1 份报价将在一周内过期：正是打电话的好时机。",
  "1 quotation is still a draft: not sent to the customer yet.": "有 1 份报价仍是草稿：尚未发送给客户。",
  "1 quotation passed its valid-until date without an answer.": "有 1 份报价已过有效期仍未获答复。",
  "1 quotation worth {amount} is waiting for the customer's answer.": "有 1 份金额 {amount} 的报价在等待客户答复。",
  "1 regular has not been back for over a month.": "有 1 位常客超过一个月没有再来。",
  "1 repair open": "1 项维修未完成",
  "1 sensitive power": "1 项敏感权限",
  "1 tap syncing…": "1 条打卡正在同步…",
