  "Approved and paid expense claims dated in the period, plus payroll cost: gross pay and the employer's SSNIT for runs approved or paid with a pay date in the period.": "日期在该期间内的已批准和已支付报销，加工资成本：支付日期在该期间内、已批准或已支付的发薪的应发工资和雇主 SSNIT。",
  "Approved and paid runs over the last six months, by the month their period ends. Deductions are PAYE plus SSNIT from staff and employer.": "过去六个月已批准和已支付的发薪，按期间结束月份统计。扣款为 PAYE 加员工和雇主的 SSNIT。",
