  "as terminated and disables their login. Their history (attendance, leave, tasks, documents) is kept for records — this does not permanently erase them.": "为离职并停用其登录权限。其历史记录（考勤、休假、任务、文档）将保留存档 — 此操作不会永久删除这些数据。",
  "Ask about attendance, stock, sales, approvals…": "可询问考勤、库存、销售、审批等…",
  "Ask about the company in plain words. It answers only from what your role can see, and when you ask it to do something it prepares it — nothing happens until you press Confirm. Press a number to go to it.": "用简单的话询问公司情况。它只根据您的角色能看到的内容回答；当您让它做某事时，它会先准备好——在您按确认之前不会发生任何事。点击数字即可跳转。",
  "Ask for something to be bought and follow it: approved, ordered, received. You get a notification at each step.": "申请采购并跟进：已批准、已下单、已收货。每一步都会通知您。",
  "Ask for time off and follow your requests. Days are working days: Sundays and public holidays are not counted.": "申请休假并跟进你的申请。天数按工作日计算：周日和公共假日不计入。",
  "Ask for time off, decide on your team's requests and see who is away, for {scope}. Days are working days: Sundays and public holidays are not counted. Press a number to show only those requests.": "申请休假、审批团队的申请并查看谁不在（{scope}）。天数按工作日计算：周日和公共假日不计入。点击数字即可只显示这些申请。",
  "Ask in your own words, in English, French or Chinese. It looks things up before answering and never changes anything without your Confirm.": "用您自己的话提问，英文、法文或中文均可。它会先查询再回答，未经您确认绝不更改任何内容。",
