  "Comments and messages logged here are tracked in Bamboo OS — a reply you send below is recorded as the reply, but doesn't post back to Facebook/Instagram/TikTok/WhatsApp itself yet (that needs the channel's live API connected first). Until then, send your reply on the actual platform and record it here.": "在此登记的评论与私信会在 Bamboo OS 中跟踪 — 您在下方发送的回复会被记录为该条回复，但目前尚不会同步发布回 Facebook/Instagram/TikTok/WhatsApp（这需要先接入该渠道的实时 API）。在此之前，请在相应平台上发送回复，然后在此登记。",
