  "Each company keeps its own list. These aren't subtracted from anyone's entitlement — a holiday that falls inside an approved leave request simply isn't charged against the balance, the same way Sundays aren't.": "每家公司各自维护自己的清单。这些日期不会从任何人的假期额度中扣除 — 落在已批准休假期间内的节假日不计入余额扣减，与星期日的处理方式相同。",
  "Each company with its departments, biggest first.": "每家公司及其部门，按人数从多到少排列。",
  "Each delivery is a batch. The bar shows how much has gone into production, been written off, or is left.": "每次送货为一个批次。条形图显示已投入生产、已报废和剩余的数量。",
  "each expires {m} minutes after it was prepared": "每项在准备后 {m} 分钟过期",
  "Each number is compared with the 30 days just before.": "每个数字都与之前 30 天进行比较。",
  "Each post drew {n} likes, comments and shares on average.": "每个帖子平均获得 {n} 次点赞、评论和分享。",
  "Each shift on the till: the cash that should be in the drawer against what was counted when it closed.": "收银台每个班次：钱箱应有现金与关班清点金额的对比。",
  "Each shift runs from its start hour to the next shift's start; the last one runs past midnight.": "每个班次从其开始时间持续到下一班次开始；最后一个班次跨过午夜。",
  "Each total is compared with the same number of days just before the dates you picked.": "每项总计都会与所选日期之前相同天数进行比较。",
