  "Every account is in order.": "所有账户都正常。",
  "Every building and the units in it that are let: who is in each one, when that ends, what stands empty and what it would bring in. Press a number to show only those.": "每栋楼及其出租单位：谁在住、何时到期、哪些空置及可带来多少租金。点击数字只显示这些。",
  "Every change made in Bamboo OS: who made it, when and what it was. Nothing here can be edited or deleted. Press a number to show only those.": "Bamboo OS 中的每一项更改：谁、何时、做了什么。这里的内容不能编辑或删除。点击数字即可只显示这些。",
  "Every claim ({n}), {amount} in all": "全部报销（{n}），合计 {amount}",
  "Every company you can see, together. Pick a company at the top to see only its people and figures.": "您可见的所有公司汇总。在顶部选择一家公司，即可只查看其人员和数据。",
  "every count matched or was over": "所有清点均相符或有盈余",
  "every day so far is in": "到目前为止每天都已录入",
  "every delivered order is invoiced": "所有已交付订单均已开票",
  "every department has one": "每个部门都有",
  "Every device is with someone who works here, checked recently and under control.": "每台设备都在在职员工手中，近期已检查，一切正常。",
  "every device seen recently": "所有设备近期都已检查",
  "Every drawer closed in the last 30 days balanced.": "最近 30 天结算的所有钱箱均平账。",
  "Every employee already has a login account.": "所有员工都已拥有登录账号。",
  "every empty unit is on offer": "所有空置单位都有报价",
  "Every finished product, what is in stock and what it is worth. The stock follows the daily stock sheet: a count, a delivery, a sale or breakage recorded here goes onto today's sheet. Press a number to show only those.": "所有成品、库存数量及其价值。库存与每日库存表同步：在此记录的清点、收货、销售或破损都会写入今天的库存表。点击数字只显示相应产品。",
  "Every invoice is paid.": "所有发票都已付清。",
  "Every invoice issued (not voided).": "所有已开具的发票（不含作废）。",
  "Every item needs at least one variation — add more later from the item's row.": "每个菜品至少需要一种规格 — 之后可在该菜品所在行继续添加。",
  "every month": "每月",
  "Every offer is out and in date, and every empty unit is on offer.": "所有报价都已发出且有效，所有空置单位都有报价。",
  "Every pay run is approved and paid, and last month is covered.": "所有发薪都已批准并支付，上个月也已覆盖。",
  "Every payslip for one employee, newest first.": "某位员工的所有工资单，最新的在前。",
  "Every permission against every role. Tick a box to grant it; the change applies at the holders' next action.": "每项权限对应每个角色。勾选即授予；更改在担任者下一次操作时生效。",
  "Every post with its likes, comments, reach and clicks — planned ones too, so the calendar shows what is coming.": "每个帖子及其点赞、评论、触达和点击——包括计划中的帖子，这样日历就能显示接下来的内容。",
  "Every post: planned, scheduled and published, newest first, with how each one did.": "所有帖子：计划中、已排期和已发布，最新的在前，并显示各自的表现。",
  "Every product": "所有产品",
  "Every product's closing stock on each day of the month that was filled in on the daily stock sheet, then the month's movements. Press a number to show only those; press a day to open that day's sheet.": "每个产品在每日库存表已填写各天的结存，以及当月的变动。点击数字只显示相应产品；点击某天打开当天的库存表。",
  "Every quotation has been answered and every accepted one is invoiced.": "所有报价都已回复，所有已接受的报价都已开票。",
  "Every quotation that left the office (not drafts).": "所有已发出的报价（不含草稿）。",
  "every reading is billed": "所有读数都已开票",
  "Every role is in use and has permissions.": "每个角色都在使用中且有权限。",
  "Every running booking is paid, has its agreement, and nothing ends without a plan.": "所有进行中的预订都已付清、有合同，到期的也都有安排。",
  "Every sale's path: the quotation, whether it was won, the invoice, and whether it has been paid.": "每笔销售的历程：报价、是否成交、发票，以及是否已付款。",
  "Every save here is recorded with what changed, from what, to what, and by whom.": "这里的每次保存都会记录更改了什么、从什么改为什么、由谁更改。",
  "Every unit is let or held back.": "所有单位都已出租或暂停出租。",
  "Every unit, two months back and six ahead; the line is today. Gaps are empty months. Press a booking to open it.": "每个单位前两个月到后六个月；竖线是今天。空白是空置月份。点击预订打开。",
  "every year": "每年",
  "Everyone": "所有人",
  "Everyone expected today has clocked in.": "今天应到的人都已打卡。",
  "Everyone has read it.": "所有人都已阅读。",
  "Everyone in the audience gets a notification when you publish.": "发布时，受众中的每个人都会收到通知。",
  "everyone is in": "全员在岗",
  "Everyone is in": "全员在岗",
  "Everyone is judged against their own shift: with 10, a 07:00 shift is late from 07:11 and an 18:00 shift from 18:11. A change applies from today — earlier days keep the rule they had.": "每个人都按自己的班次判定：设为 10 时，07:00 的班次从 07:11 起算迟到，18:00 的班次从 18:11 起算迟到。修改从今天起生效——之前的日期保留原来的规则。",
  "Everyone is paid up and every tenant has their details on file.": "所有人都已付清，每位租户的资料都已登记。",
  "everyone overdue was reminded before": "所有逾期者都已提醒过",
  "everyone reachable": "都能联系到",
  "Everyone saved at the till with a name.": "在收银台登记了姓名的所有人。",
  "Everyone together": "全部人员",
  "Everyone who works at {scope}: find a colleague, call, WhatsApp or message them, and see who is away or new. Press a number to show only those people.": "在 {scope} 工作的所有人：查找同事，打电话、发 WhatsApp 或站内消息，并查看谁不在或是新来的。点击数字即可只显示这些人。",
  "Everyone whose rent, utility bill or invoice is overdue or due soon. \"WhatsApp\" opens WhatsApp with a polite reminder and a link to the bill already written — you press send. \"Send text\" texts it straight away. Each reminder is recorded here, so nobody is chased twice in a morning.": "所有租金、水电费或发票逾期或即将到期的人。“WhatsApp”会打开 WhatsApp，并已写好礼貌的提醒和账单链接——由您按发送。“发送短信”会立即发出短信。每次提醒都会记录在此，避免同一上午重复催付。",
  "Everyone you add gets a notification. With no due date, it is due today.": "你添加的每个人都会收到通知。未设截止日期则默认今天到期。",
  "Everyone; one department only; or managers only (people who look after documents or all staff records).": "所有人；仅某一部门；或仅管理人员（负责文件或全部员工档案的人）。",
