  "Export an HR sheet as CSV (File → Download → Comma-separated values) with columns for name (or first/ last name), email, job title, company, department and hire date, and upload it here. A row's Company column disambiguates department names shared across companies (e.g. every company's own \"Kitchen\"); without it, a department name that exists in more than one company is skipped for you to fix. Unknown departments are never auto-created — create the department first from the Companies screen if it's missing.": "将人事表导出为 CSV（文件 → 下载 → 逗号分隔值），需包含姓名（或名/姓）、邮箱、职位、公司、部门和入职日期等列，然后在此上传。行中的“公司”列用于区分多家公司共用的部门名称（例如每家公司各自的“厨房”）；若缺少该列，存在于多家公司的同名部门将被跳过，留待您处理。系统绝不会自动创建未知部门 — 若部门不存在，请先在“公司”页面创建。",
  "Export CSV": "导出 CSV",
  "Export the sheet as CSV (File → Download → Comma-separated values) and upload it here. A sheet row with a Total greater than 1 becomes that many individual devices, all sharing the same brand/model.": "将表格导出为 CSV（文件 → 下载 → 逗号分隔值），然后在此上传。若某行的“总数”大于 1，则会生成相应数量的独立设备，且品牌/型号相同。",
  "Export the sheet as CSV (File → Download → Comma-separated values) and upload it here. Rows without a code get one generated automatically; rows whose code already exists are skipped, not overwritten.": "将表格导出为 CSV（文件 → 下载 → 逗号分隔值），然后在此上传。没有编号的行会自动生成编号；编号已存在的行将被跳过，不会被覆盖。",
  "Face enrolled for {firstName} {lastName}.": "已为 {firstName} {lastName} 录入人脸。",
