  "for an answer": "等待答复",
  "For bookings measured in days. Left blank, a day is charged at a thirtieth of the monthly rate.": "适用于按天计算的租约。留空时，每天按月租的三十分之一计费。",
  "For how many months": "共计多少个月",
  "For one-off charges — service charge, late fee, cleaning, damages. Rent is invoiced with its booking and metered utilities from the Utilities view, so their bookkeeping stays in step.": "用于一次性费用——服务费、滞纳金、清洁、损坏赔偿。租金随预订开票，分表水电在“水电”视图开票，保持账目一致。",
