  "Grouped by the exact tax rate on each invoice line, or set on the whole invoice. Where two configured taxes share a rate (NHIL and GETFund both default to 2.5%), the label shows both rather than guessing which applies.": "按每行发票明细的确切税率或整张发票的税率分组。若两种已配置税种税率相同（NHIL 和 GETFund 默认均为 2.5%），标签会同时列出两者，而不去猜测适用哪一种。",
