  "Has left. Their history is kept for records; turn on \"Show terminated employees\" to see them.": "已离职。其记录会保留；打开“显示已离职员工”即可查看。",
  "Has no login for the OS. They can still clock in and out at the kiosk with their PIN.": "没有系统登录账号。仍可用 PIN 在考勤机上打卡。",
  "Have {firstName} look straight at the camera, then click Capture — it walks through a few head angles (straight, left, right, up, down), about 10 seconds, to build a reference that holds up at whatever angle they happen to be at the kiosk.": "请 {firstName} 正视摄像头，然后点击“采集” — 采集会经过几个头部角度（正面、左、右、上、下），约 10 秒，以建立无论在打卡机前以何种角度都可靠的参照。",
  "Have not bought in a while: worth winning back.": "有一段时间没有购买了：值得争取回来。",
  "Headcount, who is in, late or on leave, stock running low, approvals and — with report access — revenue.": "人数、谁在岗、迟到或休假、库存不足、审批，以及（有报表权限时）收入。",
  "held back": "暂停出租",
