  "How many": "数量",
  "How many are there?": "现有多少？",
  "How many clients are at each stage. Press one to show only those.": "每个阶段有多少客户。点击一个只显示这些。",
  "How many customers are at each stage. The aim is to move people along, from lead to active and VIP.": "每个阶段有多少客户。目标是推动他们前进，从线索到活跃客户再到 VIP。",
  "How many days a new quotation stays open. After that it expires if the client hasn't answered.": "新报价保持有效的天数。之后如客户未回复即过期。",
  "How many days after issue a new invoice falls due. After that it shows as overdue.": "新发票开具后多少天到期。之后显示为逾期。",
  "How many people are in each group. Press one to see its people.": "每个组有多少人。点击一个组查看其成员。",
  "How many posts went out each day. Steady posting usually brings steady growth.": "每天发布的帖子数量。稳定发布通常带来稳定增长。",
  "How many times posts published in this period were seen.": "本期发布的帖子被查看的次数。",
  "How many times posts were seen: views on TikTok and YouTube, page views on the website, reach on Facebook and Instagram.": "帖子被查看的次数：TikTok 和 YouTube 上的观看次数，网站上的页面浏览量，Facebook 和 Instagram 上的触达。",
  "How many?": "多少？",
