  "How much more (+) or less (−) a group took than in the month before, in cedis.": "某分组比上月多收 (+) 或少收 (−) 的金额，单位为塞地。",
  "How much of the time between the start date and the deadline has passed.": "从开始日期到截止日期之间已经过去的时间比例。",
  "How much product one unit of bamboo gives, for example 2 planks per kg.": "每单位竹子可产出多少产品，例如每公斤 2 块板材。",
  "How often": "频率",
  "How often posts were seen, by the day they were published: views on TikTok and YouTube, page views on the website.": "按发布日期统计帖子被查看的次数：TikTok 和 YouTube 上的观看次数，网站上的页面浏览量。",
  "How people pay": "付款方式",
  "How someone is employed. \"By day\" means they are paid a daily rate for the days they work.": "雇佣方式。“按日”指按实际工作天数的日薪计酬。",
  "How the company is named on documents and screens.": "公司在单据和界面上的名称。",
  "How the money came in": "收款方式",
  "How the restaurant is selling, what is on the menu, the food and supplies in stock, and whether the cash drawers add up. Sales come from the till. Press a number to go to it.": "餐厅销售情况、菜单、库存的食材和用品，以及钱箱账目是否相符。销售数据来自收银台。点击数字前往查看。",
  "How this company is doing on social media and its website: who follows it, who sees its posts, and who is waiting for an answer.": "这家公司在社交媒体和网站上的表现：谁在关注、谁看到了帖子、谁在等待回复。",
  "How to pay": "付款方式",
  "How water and power are charged: paid by the tenant to the provider, read off a sub-meter, a fixed charge, or a share of the building's bill.": "水电如何收费：租户直接付给供应商、按分表读数、固定费用，或分摊整栋楼的账单。",
  "I've saved them": "我已保存",
  "IAM & Admin → Service accounts → Create service account (e.g. \"bamboo-os\"). Open it → Keys → Add key → Create new key → JSON. A .json file downloads.": "IAM 和管理 → 服务账号 → 创建服务账号（例如“bamboo-os”）。打开它 → 密钥 → 添加密钥 → 创建新密钥 → JSON。会下载一个 .json 文件。",
