  "In a week": "一周后",
  "In claude.ai or the Claude app, go to Settings → Connectors → Add custom connector and paste this address. You sign in with your OS email and password, and Claude sees only what you can see. The Claude app asks you before each change.": "在 claude.ai 或 Claude 应用中，前往 设置 → 连接器 → 添加自定义连接器，并粘贴此地址。您用 OS 的邮箱和密码登录，Claude 只能看到您能看到的内容。每次更改前 Claude 应用都会询问您。",
  "in for repair": "维修中",
  "In for repair": "维修中",
  "In Google Cloud (console.cloud.google.com), choose or create a project, then APIs & Services → Library → Google Drive API → Enable.": "在 Google Cloud（console.cloud.google.com）中选择或创建一个项目，然后进入 API 和服务 → 库 → Google Drive API → 启用。",
  "In Google Drive, share the Finish Inventory sheets — or better, the folder they are kept in — with the service account's email (it ends in iam.gserviceaccount.com), as Viewer.": "在 Google Drive 中，将 Finish Inventory 表格——最好是存放它们的文件夹——以查看者身份共享给服务账号的邮箱（以 iam.gserviceaccount.com 结尾）。",
  "In Google Drive, share the Finish Inventory sheets (or their folder) with the address above as Viewer, then open this again.": "在 Google Drive 中，将 Finish Inventory 表格（或其文件夹）以查看者身份共享给上面的地址，然后重新打开此窗口。",
  "In Google Sheets, open the \"Farmers & Suppliers\" tab, then File → Download → Comma-separated values, and upload that file here. People on the sheet more than once are merged by phone number. Uploading the sheet again later updates price, assessment, status, expected quantity and IOU — it never duplicates anyone or undoes a name you corrected here.": "在 Google 表格中打开“Farmers & Suppliers”标签页，选择 文件 → 下载 → 逗号分隔值，然后在此上传该文件。表格中出现多次的人员会按电话号码合并。日后再次上传该表格，会更新价格、评估、状态、预计数量和欠条 — 不会产生重复记录，也不会撤销您在此处更正过的姓名。",
  "In less out": "收入减支出",
  "In progress": "进行中",
  "In Render, open the backend service → Environment and add SMTP_HOST, SMTP_PORT, SMTP_USER (the full email address) and SMTP_PASS (its password), then save. MAIL_FROM is optional, e.g. Bamboo OS <no-reply@bplghana.com>.": "在 Render 中打开后端服务 → Environment，添加 SMTP_HOST、SMTP_PORT、SMTP_USER（完整邮箱地址）和 SMTP_PASS（邮箱密码），然后保存。MAIL_FROM 可选，例如 Bamboo OS <no-reply@bplghana.com>。",
  "In Render, open the backend service → Environment, add GOOGLE_SERVICE_ACCOUNT_JSON and paste the whole contents of that file. Save — the server restarts by itself.": "在 Render 中打开后端服务 → Environment，添加 GOOGLE_SERVICE_ACCOUNT_JSON 并粘贴该文件的全部内容。保存——服务器会自动重启。",
  "In Render, open the backend service → Environment, add MNOTIFY_API_KEY (the key) and MNOTIFY_SENDER_ID (the sender name), and save.": "在 Render 中打开后端服务 → Environment，添加 MNOTIFY_API_KEY（密钥）和 MNOTIFY_SENDER_ID（发件人名称），然后保存。",
  "in residence": "位在住",
  "In residence": "在住",
  "In stock": "有库存",
  "In storage": "在库",
  "in the assistant": "在助手中",
  "In the Finish Inventory sheet, open the tab for the day you counted (the tabs named 1, 2, 3 …), then File → Download → Comma-separated values, and upload that file here. Each item and variation becomes a product, with its Physical Count as the stock. Uploading a later day's tab updates the stock figures only — prices, reorder levels and names you changed here are kept.": "在 Finish Inventory 表格中，打开盘点当天的标签页（名为 1、2、3 … 的标签页），然后选择“文件 → 下载 → 逗号分隔值”，并在此上传该文件。每个物品及规格会成为一个产品，其实物盘点数即为库存。之后上传较晚日期的标签页只会更新库存数 — 在此修改过的价格、再订货水平和名称都会保留。",
