  "In the mNotify dashboard, open API and copy your API key. Check your sender name is approved there (up to 11 characters, e.g. BambooProd).": "在 mNotify 控制台中打开 API，复制您的 API 密钥。确认您的发件人名称已在那里获批（最多 11 个字符，例如 BambooProd）。",
