  "Money a client paid against one invoice. Payments are recorded from the Invoices page.": "客户针对某张发票支付的款项。付款在发票页面记录。",
  "money asked for": "申请的金额",
  "Money collected less expense claims and payroll cost, in the base currency. It leaves out purchases and other costs, so it isn't profit — see Financial reports for that.": "以本位币计算的收款减去报销和工资成本。不含采购和其他成本，因此不是利润——利润请看财务报表。",
