  "Money out": "流出",
  "Money someone spent for the business and asks to have paid back, with a photo of the receipt.": "某人为公司垫付并申请报销的费用，附收据照片。",
  "Money staff spent for the business and are claiming back: what waits for a decision, what is approved but not paid out, and where the money goes. Press a number to show only those.": "员工为公司垫付并申请报销的费用：哪些待审批、哪些已批准未报销，以及钱花在哪里。点击数字只显示这些。",
  "Money that actually moved in the period: payments and till sales in; expense claims paid out, pay runs marked paid and purchases received out. What is approved but not paid is shown separately.": "该期间实际发生的资金流动：流入为付款和收银销售；流出为已支付报销、已标记支付的发薪和已收货采购。已批准但未支付的单独列出。",
  "Money you spent for the business and are claiming back: send a claim with a photo of the receipt and follow it until it is paid.": "您为公司垫付并申请报销的费用：提交附收据照片的申请，并跟进直到报销。",
