  "once": "1 次",
  "Once enrolled, {firstName} has to look at the kiosk's camera to confirm it's them every time they tap their PIN — the PIN alone stops being enough. Nothing is stored except the measurements the camera captures right now; no photo is kept.": "录入后，{firstName} 每次输入 PIN 时都需要看向打卡机摄像头以确认身份 — 仅凭 PIN 将不再足够。除了摄像头此刻采集的测量数据外不保存任何内容；不会保留照片。",
  "One bill for the whole building, split across the units by their share, their floor area or equally.": "整栋楼的一张账单，按份额、面积或平均分摊到各单位。",
