  "One earlier shift was also clocked out automatically.": "另有 1 个更早的班次也被自动打了下班卡。",
  "One menu item at different prices, like a small and a large. The till asks which one.": "同一菜品有不同价格，如小份和大份。收银台会询问选哪一种。",
  "One of the businesses in the OS, such as Bamboo Products or a restaurant. Each has its own departments, people and figures.": "系统中的一家企业，例如 Bamboo Products 或一家餐厅。每家都有自己的部门、人员和数据。",
  "One of the clients that matter most.": "最重要的客户之一。",
  "One payment of every active employee on a cycle, for a period. It holds one payslip each.": "在某一期间向某一发薪周期的所有在职员工发放一次工资，每人一张工资单。",
  "One person's pay": "个人工资",
  "One receipt for every payment, made automatically. Open one to preview it or share it with the client as a PDF. Press a number to show only those.": "每笔付款自动生成一张收据。打开即可预览，或以 PDF 分享给客户。点击数字只显示这些。",
  "One request is waiting for your decision.": "有一项申请等待您决定。",
  "One row per person.": "每人一行。",
  "One row per person. Use the menu on a row to correct a record; every correction is written to the audit log.": "每人一行。使用行菜单更正记录；每次更正都会写入审计日志。",
  "One size, finish or version of an item, with its own code, price, cost and stock. It is what goes on a quotation or invoice line.": "项目的某一尺寸、表面处理或版本，有自己的编码、价格、成本和库存。报价或发票明细使用的就是它。",
  "One thing someone may see or do, like approving leave or viewing invoices. The server checks it on every action.": "某人可以查看或执行的一件事，例如批准休假或查看发票。服务器会在每次操作时检查。",
  "One thing was deleted, voided or cancelled in the last 30 days.": "过去 30 天有 1 项被删除、作废或取消。",
  "One-time historical import of Square customers, catalogue, orders/invoices and payments into Customers, Catalogue, Invoices & Payments (requires a Square Production Access Token set on the server).": "一次性将 Square 的客户、目录、订单／发票和付款历史导入到客户、目录、发票和付款中（需要在服务器上设置 Square 生产访问令牌）。",
