  "Only {n} text message credits are left on mNotify. Top up before reminders stop.": "mNotify 上仅剩 {n} 条短信点数。请在提醒停止前充值。",
  "Only {pct}% of orders have a guest attached. Adding the guest at the till builds the list of regulars.": "只有 {pct}% 的订单关联了宾客。在收银台添加宾客可以建立常客名单。",
