  "Optional. A record of the total agreed with this person, checked against how it is split across the leave types below. It does not limit any request.": "可选。记录与此人约定的总天数，并与下方各类假期的分配进行核对。不会限制任何申请。",
  "Or add a new guest": "或添加新宾客",
