  "Policies, licences, permits, certificates and forms in one place. Give a document an expiry date and the OS warns you before it runs out; when it is renewed, upload the new version. Press a number to show only those.": "政策、执照、许可证、证书和表格集中在一处。为文件设置到期日期，系统会在过期前提醒您；续期后上传新版本。点击数字只显示相应文件。",
