  "Press a unit for who is in it and every booking it has had.": "点击单位查看租户及所有预订记录。",
  "Press an account to see its roles, how it signs in and what happened to it lately.": "点击账户可查看其角色、登录方式以及最近的情况。",
  "Press an asset for everything done to it.": "点击资产查看所有维护记录。",
