  "Text messages aren't connected, so payment reminders, booking notices and sign-in codes by text can't go out. Add MNOTIFY_API_KEY and MNOTIFY_SENDER_ID in Render.": "短信未连接，付款提醒、预订通知和短信登录码都无法发送。请在 Render 中添加 MNOTIFY_API_KEY 和 MNOTIFY_SENDER_ID。",
