  "Welcome, {firstName}": "欢迎，{firstName}",
  "What a leave type is worth each year for everyone, unless a person has their own figure.": "某类假期每年给每个人的天数，除非个人有自己的设定。",
  "What a person can take in one year for a type. It is granted at the start of the year (or at their first request) from their days a year.": "个人一年内某类假期可休的天数。在年初（或首次申请时）按其年天数发放。",
  "What a prospect would pay to take a unit: rent up front, the deposit and the utility terms, with a date it is good until.": "意向租户入住需付的费用：预付租金、押金和水电条款，并注明有效期。",
  "What a unit costs to take, quoted to a prospect before any booking exists — costed from the unit's own rent, deposit and utilities. Accepted, it becomes a draft booking. Press a number to show only those.": "在预订之前向意向租户报出单位的费用——根据单位的租金、押金和水电计算。接受后变为预订草稿。点击数字只显示这些。",
  "What Bamboo Products sells, at what price and margin, and what actually sold. Quotations, estimates and invoices pick their lines from here. Press a number to show only those.": "Bamboo Products 销售的产品、价格和利润率，以及实际销售情况。报价、估价和发票的明细都从这里选取。点击数字只显示这些。",
  "What changed": "更改了什么",
  "What clients have been billed and what they still owe: what is overdue, what came in and what falls due next. Press a number to show only those.": "向客户开具的账单及其仍欠款项：哪些已逾期、收到了多少、接下来哪些到期。点击数字只显示这些。",
  "What condition did it come back in?": "归还时状况如何？",
