  "Who is taking it": "借用人",
  "Who is where": "谁住在哪里",
  "Who it is for (optional)": "领用人（可选）",
  "Who it is for: all staff, one company's staff or one department. Only they see it and get a notification.": "公告对象：全体员工、某家公司的员工或某个部门。只有他们能看到并收到通知。",
  "Who owes the most": "欠款最多的客户",
