  "Who sells": "谁在销售",
  "Who supplies our bamboo and materials, where they are, what they quoted, whether their bamboo meets spec, and what they have delivered. Press a number to show only those.": "谁为我们供应竹子和材料、他们在哪里、报价多少、竹子是否符合规格，以及已交付多少。点击数字只显示相应供应商。",
  "Who supplies what, and how to reach them.": "谁供应什么，以及如何联系他们。",
