  "You": "你",
  "You already have a face on file — continuing replaces it.": "您已录入过人脸 — 继续操作将覆盖原有数据。",
  "You are almost out of {types}.": "你的{types}快用完了。",
  "you are told when it arrives": "到货时会通知您",
  "you are up to date": "你已看完所有内容",
  "You are up to date: nothing new since you last looked.": "你已看完所有内容：自上次查看以来没有新公告。",
  "You can also upload the monthly summary tab (e.g. \"2026 Sept\"): it brings in each day's figure as stock history, and its latest day as the stock.": "也可以上传月度汇总工作表（例如“2026 Sept”）：每天的数字会记入库存历史，最后一天的数字作为库存。",
  "You can generate a share link or send this by WhatsApp once it's created — open it from the list and click Preview.": "创建完成后，您可以生成分享链接或通过 WhatsApp 发送 — 在列表中打开它并点击“预览”。",
  "You can see the sheet; people who manage the stock fill it in.": "您可以查看此表；由管理库存的人员填写。",
  "You can see these settings but your role can't change them. Ask someone with Company settings access.": "您可以查看这些设置，但您的角色无法更改。请联系有公司设置权限的人。",
  "You can send up to {n} files at a time.": "一次最多可发送 {n} 个文件。",
  "You can't change your own roles.": "您不能更改自己的角色。",
  "You clocked in at {clockIn} on {date} but didn't clock out, so the system clocked you out automatically at {clockOut}, {hours} hours later.": "您在 {date} {clockIn} 打了上班卡，但没有打下班卡，因此系统在 {hours} 小时后的 {clockOut} 自动为您打了下班卡。",
  "You confirmed you have read this": "你已确认阅读",
  "You have {n} days of {type} left this year.": "你今年的{type}还剩 {n} 天。",
  "You have {n} tasks due today.": "你有 {n} 个任务今天到期。",
  "You have changes that aren't saved yet.": "您有尚未保存的更改。",
  "You haven't clocked in yet today. Your shift started at {time}.": "您今天还没有打卡。您的班次已于 {time} 开始。",
  "You need to set your own before continuing.": "继续之前，您需要先设置自己的。",
  "You still have {n} days of paid leave this year. Plan them before 31 December.": "您今年还有 {n} 天带薪假。请在 12 月 31 日前安排。",
  "You will have {left} of {total} days left.": "你将剩余 {left} 天（共 {total} 天）。",
  "You're {n} minutes late": "您迟到了 {n} 分钟",
  "You're 1 minute late": "您迟到了 1 分钟",
  "you're all caught up": "全部处理完毕",
  "You're all caught up": "您已处理完所有事项",
  "You're all caught up. Requests from the people you're responsible for will appear here.": "全部处理完毕。您负责的人员提出的申请会显示在这里。",
  "You're all set! Face recognition is now active for your clock-ins. You can close this page.": "设置完成！人脸识别打卡已启用。您可以关闭此页面。",
  "You're on time": "您准时到岗",
  "You've been clocked in since {time} on {date}. Clock out if you have finished.": "您自 {date} {time} 起一直处于打卡状态。如已下班，请打卡下班。",
  "Your {category} claim of {amount} was rejected.": "您 {amount} 的{category}报销被拒绝。",
